190			value = REG_READ(REG_FLASH_SR_DATA_CRC_CNT);
191			sr |= (value & 0x00FF) << 8;
192		}
193	
194		BK_LOGV(TAG, "--read sr:%x--\r\n",sr);
195	
196		return sr;
