502	static void flash_erase_sector(UINT32 address)
503	{
504		UINT32 value;
505		UINT32 erase_addr = address & 0xFFF000;
506	
507		if (erase_addr >= flash_current_config->flash_size) {
508			BK_LOGE("Erase error:invalid address0x%x\r\n", erase_addr);
509			return;
510		}
511	
512		while (REG_READ(REG_FLASH_OPERATE_SW) & BUSY_SW);
513		value = REG_READ(REG_FLASH_OPERATE_SW);
514		value = ((erase_addr << ADDR_SW_REG_POSI)
515				 | (FLASH_OPCODE_SE << OP_TYPE_SW_POSI)
516				 | OP_SW
517				 | (value & WP_VALUE));
518		REG_WRITE(REG_FLASH_OPERATE_SW, value);
519		while (REG_READ(REG_FLASH_OPERATE_SW) & BUSY_SW);
520	}
