536	static void flash_read_data(UINT8 *buffer, UINT32 address, UINT32 len)
537	{
538		UINT32 i, reg_value;
539		UINT32 addr = address & (~0x1F);
540		UINT32 buf[8];
541		UINT8 *pb = (UINT8 *)&buf[0];
542	
543		if (len == 0)
544			return;
545	
546		while (REG_READ(REG_FLASH_OPERATE_SW) & BUSY_SW);
547		while (len) {
548			reg_value = REG_READ(REG_FLASH_OPERATE_SW);
549			reg_value = ((addr << ADDR_SW_REG_POSI)
550						 | (FLASH_OPCODE_READ << OP_TYPE_SW_POSI)
551						 | OP_SW
552						 | (reg_value & WP_VALUE));
553			REG_WRITE(REG_FLASH_OPERATE_SW, reg_value);
554			while (REG_READ(REG_FLASH_OPERATE_SW) & BUSY_SW);
555			addr += 32;
556	
557			for (i = 0; i < 8; i++)
558				buf[i] = REG_READ(REG_FLASH_DATA_FLASH_SW);
559	
560			for (i = address % 32; i < 32; i++) {
561				*buffer++ = pb[i];
562				address++;
563				len--;
564				if (len == 0)
565					break;
566			}
567		}
568	}
569	
570	static void flash_write_data(UINT8 *buffer, UINT32 address, UINT32 len)
571	{
572		UINT32 i, reg_value;
573		UINT32 addr = address & (~0x1F);
574		UINT32 buf[8];
575		UINT8 *pb = (UINT8 *)&buf[0];
576	
577		if ((addr >= flash_current_config->flash_size)
578			|| (len > flash_current_config->flash_size)
579			|| ((addr + len) > flash_current_config->flash_size)) {
580			BK_LOGE("Write error[addr:0x%x len:0x%x]\r\n", addr, len);
581			return;
582		}
583	
584		if (address % 32)
585			flash_read_data(pb, addr, 32);
586		else
587			os_memset(pb, 0xFF, 32);
588	
589		while (REG_READ(REG_FLASH_OPERATE_SW) & BUSY_SW);
590		while (len) {
591			if (len < 32) {
592				flash_read_data(pb, addr, 32);
593				while (REG_READ(REG_FLASH_OPERATE_SW) & BUSY_SW);
594			}
595			for (i = address % 32; i < 32; i++) {
596				pb[i] = *buffer++;
597				address++;
598				len--;
599				if (len == 0)
600					break;
601			}
602	
603			for (i = 0; i < 8; i++)
604				REG_WRITE(REG_FLASH_DATA_SW_FLASH, buf[i]);
605	
606			reg_value = REG_READ(REG_FLASH_OPERATE_SW);
607			reg_value = ((addr << ADDR_SW_REG_POSI)
608						 | (FLASH_OPCODE_PP << OP_TYPE_SW_POSI)
609						 | OP_SW
610						 | (reg_value & WP_VALUE));
611			REG_WRITE(REG_FLASH_OPERATE_SW, reg_value);
612			while (REG_READ(REG_FLASH_OPERATE_SW) & BUSY_SW);
613			addr += 32;
614			os_memset(pb, 0xFF, 32);
615		}
616	}
