685	static bk_err_t flash_erase_no_lock(uint32_t address, int cmd)
686	{
687		if (address >= s_flash.flash_cfg->flash_size) {
688			FLASH_LOGW("erase error:invalid address 0x%x\r\n", address);
689			return BK_ERR_FLASH_ADDR_OUT_OF_RANGE;
690		}
691	
692		uint32_t  erase_size = 0;
693	
694		if(cmd == FLASH_OP_CMD_SE)
695			erase_size = FLASH_SECTOR_SIZE;
696		else if(cmd == FLASH_OP_CMD_BE1)
697			erase_size = FLASH_BLOCK32_SIZE;
698		else if(cmd == FLASH_OP_CMD_BE2)
699			erase_size = FLASH_BLOCK_SIZE;
700		else
701			return BK_FAIL;
702	
703		uint32_t erase_addr = address & (~(erase_size - 1));
704	
705		bk_err_t    ret_val = BK_FAIL;
706	
707		flash_line_mode_t old_line_mode = flash_set_line_mode(FLASH_LINE_MODE_TWO);
708	#if CONFIG_FLASH_WRITE_STATUS_VOLATILE  //bk7258 default as protect none to improve erase/write performance
709		uint32_t  status_reg = s_flash.flash_status_reg_val;
710		#if CONFIG_FLASH_SUPPORT_MULTI_PE
711		status_reg = flash_read_status_reg();
712		#endif
713	
714	    flash_protect_type_t partition_type = flash_get_protect_type(status_reg);
715	#endif
716		if(bk_flash_partition_write_perm_check_by_addr(erase_addr, erase_size, FLASH_API_MAGIC_CODE) == BK_OK)
717		{
718	    	flash_set_protect_type(FLASH_PROTECT_NONE);
719	
720			if(bk_flash_partition_write_perm_check_by_addr(erase_addr, erase_size, FLASH_API_MAGIC_CODE) == BK_OK)
721				ret_val = flash_erase_block(address, cmd);
722		}
723	
724	#if CONFIG_FLASH_WRITE_STATUS_VOLATILE  //bk7258 default as protect none to improve erase/write performance
725	    flash_set_protect_type(partition_type);
726	#endif
727		flash_set_line_mode(old_line_mode);
728	
729		return ret_val;
730	}
