732	bk_err_t bk_flash_erase_sector(uint32_t address)
733	{
734		if (address >= s_flash.flash_cfg->flash_size) {
735			FLASH_LOGW("erase error:invalid address 0x%x\r\n", address);
736			return BK_ERR_FLASH_ADDR_OUT_OF_RANGE;
737		}
738	
739		flash_lock();
740	
741		bk_err_t ret_val = flash_erase_no_lock(address, FLASH_OP_CMD_SE);
742	
743		flash_unlock();
744	
745		return ret_val;
746	}
