2	 * contest2026_135_yongwangzhiqian/board/bk7258_t5ai/chip/bk7258_clockdiag.h
3	 *
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * BK7258 Stage N4 clock/SysTick diagnostics and gated clock probes.
7	 *
8	 * Most helpers are read-only register snapshots used to explain the clock
9	 * state left by the Tier-1 bootloader.  The bk7258_clockdiag_try_dpll*()
10	 * helpers are explicit bring-up probes and keep their original board-tested
11	 * gating conditions.
12	 *
13	 * Contract: the including translation unit must include arm_internal.h first
14	 * so getreg32()/putreg32() are available.
15	 ****************************************************************************/
16	
17	#ifndef __ARCH_ARM_SRC_BK7258_CHIP_BK7258_CLOCKDIAG_H
18	#define __ARCH_ARM_SRC_BK7258_CHIP_BK7258_CLOCKDIAG_H
19	
20	/****************************************************************************
21	 * Included Files
22	 ****************************************************************************/
23	
24	#include <nuttx/config.h>
25	#include <stdint.h>
26	
27	/* Peripheral base addresses (Armino cp/include/soc/bk7258/reg_base.h). */
28	
29	#define BK7258_CDIAG_SYS_BASE        0x44010000u   /* SOC_SYS_REG_BASE     */
30	#define BK7258_CDIAG_AON_PMU_BASE    0x44000000u   /* SOC_AON_PMU_REG_BASE */
31	#define BK7258_CDIAG_UART1_BASE      0x45830000u   /* SOC_UART1_REG_BASE   */
32	
33	/* SYS register offsets (Armino soc/bk7258/soc/sys_reg.h, ADDR == base +
34	 * (index << 2)).  Raw values only; never written by this header.
35	 */
36	
37	/* Per-core CPU0 clock-operating register (SYS_CPU0_INT_HALT_CLK_OP).  Note:
38	 * the BK7258 has NO per-core clock *divider* field -- the core divider is
39	 * the shared global CLKDIV_CORE in CPU_CLK_DIV_MODE1 (dumped as "cdiv"
40	 * below and applying to CPU0/CPU1/CPU2 alike).  The only per-core clock
41	 * field is CPU0_SPEED [4] here (1-bit speed select); CPU1/CPU2 mirror this
42	 * at indexes 0x05/0x06.  Read-only.
43	 */
44	
45	#define BK7258_CDIAG_SYS_CPU0_HALT_CLK_OP \
46	        (BK7258_CDIAG_SYS_BASE + (0x04u << 2))            /* 0x44010010 */
47	#define BK7258_CDIAG_SYS_CPU_CLK_DIV_MODE1 \
48	        (BK7258_CDIAG_SYS_BASE + (0x08u << 2))            /* 0x44010020 */
49	#define BK7258_CDIAG_SYS_CPU_CLK_DIV_MODE2 \
50	        (BK7258_CDIAG_SYS_BASE + (0x09u << 2))            /* 0x44010024 */
51	#define BK7258_CDIAG_SYS_CPU0_INT_32_63_STAT \
52	        (BK7258_CDIAG_SYS_BASE + (0x29u << 2))            /* 0x440100A4 */
53	#define BK7258_CDIAG_SYS_ANA_REG0 \
54	        (BK7258_CDIAG_SYS_BASE + (0x40u << 2))            /* 0x44010100 */
55	#define BK7258_CDIAG_SYS_ANA_REG1 \
56	        (BK7258_CDIAG_SYS_BASE + (0x41u << 2))            /* 0x44010104 */
57	#define BK7258_CDIAG_SYS_ANA_REG5 \
58	        (BK7258_CDIAG_SYS_BASE + (0x45u << 2))            /* 0x44010114 */
59	#define BK7258_CDIAG_SYS_ANA_REG8 \
60	        (BK7258_CDIAG_SYS_BASE + (0x48u << 2))            /* 0x44010120 */
61	#define BK7258_CDIAG_SYS_ANA_REG9 \
62	        (BK7258_CDIAG_SYS_BASE + (0x49u << 2))            /* 0x44010124 */
63	#define BK7258_CDIAG_SYS_ANA_REG10 \
64	        (BK7258_CDIAG_SYS_BASE + (0x4au << 2))            /* 0x44010128 */
65	#define BK7258_CDIAG_SYS_ANA_REG11 \
66	        (BK7258_CDIAG_SYS_BASE + (0x4bu << 2))            /* 0x4401012C */
67	#define BK7258_CDIAG_SYS_ANA_REG12 \
68	        (BK7258_CDIAG_SYS_BASE + (0x4cu << 2))            /* 0x44010130 */
69	#define BK7258_CDIAG_SYS_ANA_REG13 \
70	        (BK7258_CDIAG_SYS_BASE + (0x4du << 2))            /* 0x44010134 */
71	
72	/* AON_PMU register offset (Armino soc/bk7258/soc/aon_pmu_reg.h). */
73	
74	#define BK7258_CDIAG_AON_PMU_R7D \
75	        (BK7258_CDIAG_AON_PMU_BASE + (0x7du << 2))        /* 0x440001F4 */
76	
77	/* UART1 config register holding clk_div (Armino uart_struct.h: config is
78	 * REG_0x04 -> base + 0x10, clk_div bits[8:23]).  Read-only here -- this is
79	 * the register the Tier-1 bootloader programmed; the N2 console contract
80	 * forbids writing it.
81	 */
82	
83	#define BK7258_CDIAG_UART1_CFG_REG    (BK7258_CDIAG_UART1_BASE + 0x10u) /* 0x45830010 */
84	
85	/* UART1 FIFO status/port for the freestanding polled putc (identical MMIO
86	 * offsets to bk7258_start.c / bk7258_timerisr.c / bk7258_vectors.c).
87	 */
88	
89	#define BK7258_CDIAG_UART1_FSTAT \
90	        (*(volatile uint32_t *)(BK7258_CDIAG_UART1_BASE + 0x18u)) /* 0x45830018 */
91	#define BK7258_CDIAG_UART1_FPORT \
92	        (*(volatile uint32_t *)(BK7258_CDIAG_UART1_BASE + 0x1cu)) /* 0x4583001C */
93	#define BK7258_CDIAG_UART1_READY      (1u << 20)  /* fifo_status.bit20 fifo_wr_ready */
94	
95	/* SysTick CSR/RVR/CVR -- standard ARMv7-M/ARMv8-M addresses (identical to
96	 * nuttx NVIC_SYSTICK_CTRL/RELOAD/CURRENT); inlined so this header does not
97	 * require nvic.h in every including translation unit.
98	 */
99	
100	#define BK7258_CDIAG_SYSTICK_CSR      0xe000e010u
101	#define BK7258_CDIAG_SYSTICK_RVR      0xe000e014u
102	#define BK7258_CDIAG_SYSTICK_CVR      0xe000e018u
103	
104	/* Field bit definitions for the compact decode line (source: Armino
105	 * soc/bk7258/soc/sys_reg.h + uart_struct.h).
106	 *
107	 *   CPU_CLK_DIV_MODE1:
108	 *     CLKDIV_CORE  [0:3]   core divider (shared by all CPUs -- this IS the
109	 *                          CPU0 core divider; no per-core divider exists)
110	 *     CKSEL_CORE   [4:5]   core source select
111	 *     CLKDIV_BUS   [6]     bus divider
112	 *     CLKDIV_UART1 [11:12] uart1 divider field
113	 *     CKSEL_UART1  [13]    uart1 source select
114	 *   CPU0_INT_HALT_CLK_OP:
115	 *     CPU0_SPEED   [4]     per-core CPU0 speed select (clock-op bit)
116	 *   CPU_CLK_DIV_MODE2:
117	 *     CKSEL_FLASH  [24:25] flash source select
118	 *     CKDIV_FLASH  [26:27] flash divider
119	 *   ANA_REG5:
120	 *     EN_DPLL      [5]     DPLL enable
121	 *   CPU0_INT_32_63_STATUS:
122	 *     DPLL_UNLOCK_INT_ST [19]  DPLL unlock status (sticky live read)
123	 *   ANA_REG9:
124	 *     VCOREHSEL    [16:19] core voltage select
125	 *   UART1 config:
126	 *     clk_div      [8:23]  uart clock divider (uart_clk / baud)
127	 */
128	
129	#define BK7258_CDIAG_F_CKSEL_CORE(v)   (((v) >> 4)  & 0x3u)
130	#define BK7258_CDIAG_F_CLKDIV_CORE(v)  (((v) >> 0)  & 0xfu)
131	#define BK7258_CDIAG_F_CLKDIV_BUS(v)   (((v) >> 6)  & 0x1u)
132	#define BK7258_CDIAG_F_CLKDIV_UART1(v) (((v) >> 11) & 0x3u)
133	#define BK7258_CDIAG_F_CKSEL_UART1(v)  (((v) >> 13) & 0x1u)
134	#define BK7258_CDIAG_F_CKSEL_FLASH(v)  (((v) >> 24) & 0x3u)
135	#define BK7258_CDIAG_F_CKDIV_FLASH(v)  (((v) >> 26) & 0x3u)
136	#define BK7258_CDIAG_F_EN_DPLL(v)      (((v) >> 5)  & 0x1u)
137	#define BK7258_CDIAG_F_DPLL_UNLOCK(v)  (((v) >> 19) & 0x1u)
138	#define BK7258_CDIAG_F_VCOREHSEL(v)    (((v) >> 16) & 0xfu)
139	#define BK7258_CDIAG_F_UART_CLKDIV(v)  (((v) >> 8)  & 0xffffu)
140	#define BK7258_CDIAG_F_CPU0_SPEED(v)   (((v) >> 4)  & 0x1u)
141	
