225	static inline void bk7258_clockdiag_try_dpll120(void)
226	{
227	  uint32_t m1;
228	  uint32_t a5;
229	  uint32_t new_m1;
230	
231	  m1 = getreg32(BK7258_CDIAG_SYS_CPU_CLK_DIV_MODE1);
232	  a5 = getreg32(BK7258_CDIAG_SYS_ANA_REG5);  /* ANA_REG5 */
233	
234	  /* Only run on the already-observed loader residue path:
235	    * M1=0x423 means csrc=2,cdiv=3.
236	    * ANA_REG5[5] dplle must already be 1.
237	    * Manual-reset baseline must not be touched.
238	    */
239	
240	  if (m1 != 0x00000423u)
241	    {
242	      return;
243	    }
244	
245	  if (((a5 >> 5) & 1u) == 0)
246	    {
247	      return;
248	    }
249	
250	  bk7258_clockdiag_puts("N4D0:120S\r\n");
251	
252	  /* Keep clkdiv_core unchanged, only change cksel_core bits [5:4]
253	    * from 2 to 3:
254	    *
255	    * old M1 = 0x423
256	    * new M1 = 0x433
257	    */
258	
259	  new_m1 = (m1 & ~(0x3u << 4)) | (0x3u << 4);
260	
261	  __asm__ volatile ("dsb 0xf" ::: "memory");
262	  putreg32(new_m1, BK7258_CDIAG_SYS_CPU_CLK_DIV_MODE1);
263	  __asm__ volatile ("dsb 0xf" ::: "memory");
264	  __asm__ volatile ("isb 0xf" ::: "memory");
265	
266	  bk7258_clockdiag_putreg("N4D0:120M M1",
267	                          getreg32(BK7258_CDIAG_SYS_CPU_CLK_DIV_MODE1));
268	  bk7258_clockdiag_puts("\r\n");
269	}
