451	/* Runtime CPU-frequency case identifiers used by
452	 * bk7258_clockdiag_last_clock_case() and bk7258_clockdiag_current_cpu_hz().
453	 * The case is decided from a read-only snapshot of CPU_CLK_DIV_MODE1 (M1)
454	 * and ANA_REG5 (A5) -- never from a write.
455	 */
456	
457	#define BK7258_CDIAG_CASE_BASELINE   0   /* M1=0 dplle=0: 26 MHz XTAL.      */
458	#define BK7258_CDIAG_CASE_LOADER80   1   /* M1=0x423 csrc=2 cdiv=3 dplle=1:
459	                                         * loader --reboot 1 residue, ~80 MHz
460	                                         */
461	#define BK7258_CDIAG_CASE_DPLL120    2
462	#define BK7258_CDIAG_CASE_DPLL160    3
463	#define BK7258_CDIAG_CASE_DPLL240    4
464	#define BK7258_CDIAG_CASE_DPLL320    5
465	#define BK7258_CDIAG_CASE_DPLL480    6
466	#define BK7258_CDIAG_CASE_UNKNOWN    7   /* fallback to baseline hz.        */
467	/****************************************************************************
468	 * Name: bk7258_clockdiag_last_clock_case
469	 *
470	 * Description:
471	 *   Classify the live core-clock configuration from a read-only snapshot of
472	 *   CPU_CLK_DIV_MODE1 (M1) and ANA_REG5 (A5).  No register is written.
473	 *   Recognised cases:
474	 *
475	 *     BK7258_CDIAG_CASE_BASELINE  Manual-reset BootROM default: M1 = 0 with
476	 *                                 DPLL disabled -- 26 MHz XTAL.
477	 *     BK7258_CDIAG_CASE_LOADER80  Tier-1 loader `--reboot 1` residue:
478	 *                                 M1 = 0x00000423 with csrc = 2, cdiv = 3
479	 *                                 and DPLL enabled -- observed f_cpu ~80.04
480	 *                                 MHz (J-Link DWT, 2 s = 0x098AA02F ticks).
481	 *     BK7258_CDIAG_CASE_UNKNOWN   Any other combination; callers fall back
482	 *                                 to the baseline frequency.
483	 *
484	 ****************************************************************************/
485	
486	static inline int bk7258_clockdiag_last_clock_case(void)
487	{
488	  uint32_t m1    = getreg32(BK7258_CDIAG_SYS_CPU_CLK_DIV_MODE1);
489	  uint32_t a5    = getreg32(BK7258_CDIAG_SYS_ANA_REG5);
490	  uint32_t csrc  = BK7258_CDIAG_F_CKSEL_CORE(m1);
491	  uint32_t cdiv  = BK7258_CDIAG_F_CLKDIV_CORE(m1);
492	  uint32_t dplle = BK7258_CDIAG_F_EN_DPLL(a5);
493	
494	  if (m1 == 0x00000000u && dplle == 0u)
495	    {
496	      return BK7258_CDIAG_CASE_BASELINE;
497	    }
498	
499	  if (m1 == 0x00000423u && csrc == 2u && cdiv == 3u && dplle == 1u)
500	    {
501	      return BK7258_CDIAG_CASE_LOADER80;
502	    }
503	  if (m1 == 0x00000433u && csrc == 3 && cdiv == 3 && dplle)
504	    {
505	      return BK7258_CDIAG_CASE_DPLL120;
506	    }
507	  if (m1 == 0x00000432u && csrc == 3 && cdiv == 2 && dplle)
508	    {
509	      return BK7258_CDIAG_CASE_DPLL160;
510	    }
511	  if (m1 == 0x00000431u && csrc == 3 && cdiv == 1 && dplle)
512	    {
513	      return BK7258_CDIAG_CASE_DPLL240;
514	    }
515	  if (m1 == 0x00000420u && csrc == 2 && cdiv == 0 && dplle)
516	    {
517	      return BK7258_CDIAG_CASE_DPLL320;
518	    }
519	  if (m1 == 0x00000430u && csrc == 3 && cdiv == 0 && dplle)
520	    {
521	      return BK7258_CDIAG_CASE_DPLL480;
522	    }
523	  return BK7258_CDIAG_CASE_UNKNOWN;
524	}
525	
526	/****************************************************************************
527	 * Name: bk7258_clockdiag_current_cpu_hz
528	 *
529	 * Description:
530	 *   Return the runtime SysTick processor-clock frequency in Hz inferred
531	 *   from the live M1 and A5 registers.  Maps each case from
532	 *   bk7258_clockdiag_last_clock_case() to its measured frequency, and falls
533	 *   back to the 26 MHz baseline for the unknown case.  Read-only; no
534	 *   clock-control register is written.
535	 *
536	 *   The returned value is the SysTick processor clock (CLKSOURCE = processor
537	 *   clock, no /8 divisor).  BOARD_CPU_FREQ_HZ in board.h remains the
538	 *   build-time baseline and matches the BK7258_CDIAG_CASE_BASELINE return.
539	 *
540	 ****************************************************************************/
541	
542	static inline uint32_t bk7258_clockdiag_current_cpu_hz(void)
543	{
544	  switch (bk7258_clockdiag_last_clock_case())
545	    {
546	      case BK7258_CDIAG_CASE_BASELINE:
547	        return 26000000u;
548	
549	      case BK7258_CDIAG_CASE_LOADER80:
550	        return 80000000u;
551	
552	      case BK7258_CDIAG_CASE_DPLL120:
553	        return 120000000u;
554	
555	      case BK7258_CDIAG_CASE_DPLL160:
556	        return 160000000u;
557	      
558	      case BK7258_CDIAG_CASE_DPLL240:
559	        return 240000000u;
560	
561	      case BK7258_CDIAG_CASE_DPLL320:
562	        return 320000000u;
563	
564	      case BK7258_CDIAG_CASE_DPLL480:
565	        return 480000000u;
566	
567	      default:
568	        return 26000000u;
569	    }
570	}
571	
572	
573	
574	/****************************************************************************
575	 * Name: bk7258_clockdiag_systick_dump
576	 *
577	 * Description:
578	 *   Read-only snapshot of the Cortex-M SysTick CSR/RVR/CVR.  Intended to be
579	 *   called exactly once from up_timer_initialize() in bk7258_timerisr.c
580	 *   AFTER the reload write and systick_initialize() have programmed the
581	 *   SysTick, so the read-back captures the live armed state.
582	 *
583	 *   `expected_reload` is the value the caller computed at runtime (from
584	 *   bk7258_clockdiag_current_cpu_hz() and CLK_TCK) and wrote into RVR; the
585	 *   dump emits it as EXP so the read-back RVR can be compared against the
586	 *   design reload.  `cpu_hz` is the runtime frequency the caller used; the
587	 *   dump emits it as HZ plus the matched clock-case tag (CLK=x) so board-
588	 *   side observation can distinguish baseline / loader-residue / unknown
589	 *   without parsing the full early dump.  No SysTick register is written by
590	 *   this call -- the existing reload write in up_timer_initialize() is the
591	 *   only write, and is not a new clock write.
592	 *
593	 ****************************************************************************/
594	
595	static inline void bk7258_clockdiag_systick_dump(uint32_t expected_reload,
596	                                                 uint32_t cpu_hz)
597	{
598	  uint32_t csr = getreg32(BK7258_CDIAG_SYSTICK_CSR);
599	  uint32_t rvr = getreg32(BK7258_CDIAG_SYSTICK_RVR);
600	  uint32_t cvr = getreg32(BK7258_CDIAG_SYSTICK_CVR);
601	  int clk_case  = bk7258_clockdiag_last_clock_case();
602	
603	  bk7258_clockdiag_puts("N4D0:T\r\n");
604	
605	   bk7258_clockdiag_putreg("CSR", csr);
606	  bk7258_clockdiag_putc(' ');
607	   bk7258_clockdiag_putreg("RVR", rvr);
608	  bk7258_clockdiag_putc(' ');
609	   bk7258_clockdiag_putreg("CVR", cvr);
610	  bk7258_clockdiag_putc(' ');
611	   bk7258_clockdiag_putreg("EXP", expected_reload);
612	  bk7258_clockdiag_putc(' ');
613	   bk7258_clockdiag_putreg("HZ", cpu_hz);
614	  bk7258_clockdiag_putc(' ');
615	  bk7258_clockdiag_putfield("CLK", (uint32_t)clk_case, 1);
616	  bk7258_clockdiag_puts("\r\n");
617	}
618	
