110	static inline int bk7258_clockdiag_flash_wait_ready(void)
111	{
112	  uint32_t timeout = BK7258_CDIAG_FLASH_TIMEOUT;
113	
114	  while ((getreg32(BK7258_CDIAG_FLASH_OP_CTRL) &
115	          BK7258_CDIAG_FLASH_BUSY_BIT) != 0)
116	    {
117	      if (--timeout == 0)
118	        {
119	          return -1;
120	        }
121	    }
122	
123	  return 0;
124	}
