128	static inline uint32_t bk7258_clockdiag_flash_read_id(void)
129	{
130	  uint32_t cmd;
131	  uint32_t ctrl;
132	
133	  if (bk7258_clockdiag_flash_wait_ready() < 0)
134	    {
135	      return 0;
136	    }
137	
138	  /* op_cmd.op_type_sw is bits [24:28]. RDID command is controller op 20. */
139	
140	  cmd = BK7258_CDIAG_FLASH_OP_CMD_RDID << 24;
141	  putreg32(cmd, BK7258_CDIAG_FLASH_OP_CMD);
142	
143	  ctrl = getreg32(BK7258_CDIAG_FLASH_OP_CTRL);
144	  putreg32(ctrl | BK7258_CDIAG_FLASH_OP_SW_BIT,
145	            BK7258_CDIAG_FLASH_OP_CTRL);
146	
147	  if (bk7258_clockdiag_flash_wait_ready() < 0)
148	    {
149	      return 0;
150	    }
151	
152	  return getreg32(BK7258_CDIAG_FLASH_RD_ID);
153	}
