161	      case 0x00c84017u:
162	      case 0x00c86517u:
163	      case 0x00cd6017u:
164	        return 0x00800000u;
165	
166	      default:
167	        return 0;
168	    }
169	}
170	static inline int bk7258_clockdiag_flash_read16(uint32_t addr,
171	                                                uint32_t out[4])
172	{
173	  uint32_t cmd;
174	  uint32_t ctrl;
175	  unsigned int i;
176	
177	  if (bk7258_clockdiag_flash_wait_ready() < 0)
178	    {
179	      return -1;
180	    }
181	
182	  cmd = (addr & 0x00ffffffu) |
183	        (BK7258_CDIAG_FLASH_OP_CMD_READ << 24);
184	  putreg32(cmd, BK7258_CDIAG_FLASH_OP_CMD);
185	
186	  ctrl = getreg32(BK7258_CDIAG_FLASH_OP_CTRL);
187	  putreg32(ctrl | BK7258_CDIAG_FLASH_OP_SW_BIT,
188	            BK7258_CDIAG_FLASH_OP_CTRL);
189	
190	  if (bk7258_clockdiag_flash_wait_ready() < 0)
191	    {
192	      return -1;
193	    }
194	
195	  for (i = 0; i < 4; i++)
196	    {
197	      out[i] = getreg32(BK7258_CDIAG_FLASH_DATA_IN);
198	    }
199	
200	  return 0;
201	}
