282	static inline int bk7258_clockdiag_flash_write_sr1(uint32_t sr1)
283	{
284	  uint32_t conf0;
285	  uint32_t conf;
286	  int ret;
287	
288	  if (bk7258_clockdiag_flash_wren_plain() < 0)
289	    {
290	      return -1;
291	    }
292	
293	  putreg32(0u, BK7258_CDIAG_FLASH_CMD_CFG);
294	
295	  conf0 = getreg32(BK7258_CDIAG_FLASH_CONF);
296	  conf = conf0 & ~BK7258_CDIAG_FLASH_WRSR_DATA_MASK;
297	  conf |= (sr1 & 0xffu) << BK7258_CDIAG_FLASH_WRSR_DATA_SHIFT;
298	  putreg32(conf, BK7258_CDIAG_FLASH_CONF);
299	
300	  ret = bk7258_clockdiag_flash_swop_wp(0u,
301	                                        BK7258_CDIAG_FLASH_OP_CMD_WRSR);
302	
303	  putreg32(conf0, BK7258_CDIAG_FLASH_CONF);
304	
305	  return ret;
306	}
307	static inline uint32_t bk7258_clockdiag_flash_read_sr(uint32_t op)
308	{
309	  if (bk7258_clockdiag_flash_swop_plain(0u, op) < 0)
310	    {
311	      return 0xffffffffu;
312	    }
313	
314	  return getreg32(BK7258_CDIAG_FLASH_STATE) & 0xffu;
315	}
316	static inline int bk7258_clockdiag_flash_d5_unprotect(uint32_t *saved_sr0)
317	{
318	  uint32_t sr0;
319	  uint32_t unprotect_sr0;
320	
321	  sr0 = bk7258_clockdiag_flash_read_sr(BK7258_CDIAG_FLASH_OP_CMD_RDSR);
322	  if (sr0 == 0xffffffffu)
323	    {
324	      return -1;
325	    }
326	
327	  *saved_sr0 = sr0;
328	
329	  if ((sr0 & BK7258_CDIAG_FLASH_SR1_PROTECT_MASK) == 0)
330	    {
331	      return 0;
332	    }
333	
334	  /* Clear protection bits. Do not try to write WIP/WEL. */
335	
336	  unprotect_sr0 = sr0 & ~BK7258_CDIAG_FLASH_SR1_PROTECT_MASK;
337	  unprotect_sr0 &= ~0x03u;
338	
339	  if (bk7258_clockdiag_flash_write_sr1(unprotect_sr0) < 0)
340	    {
341	      return -1;
342	    }
343	
344	  sr0 = bk7258_clockdiag_flash_read_sr(BK7258_CDIAG_FLASH_OP_CMD_RDSR);
345	  if ((sr0 & BK7258_CDIAG_FLASH_SR1_PROTECT_MASK) != 0)
346	    {
347	      return -1;
348	    }
349	
350	  return 1;
351	}
