353	static inline int bk7258_clockdiag_flash_d5_restore(uint32_t saved_sr0,
354	                                                    int changed)
355	{
356	  uint32_t restore_sr0;
357	
358	  if (!changed)
359	    {
360	      return 0;
361	    }
362	
363	  /* Restore writable protection bits; WIP/WEL are read-only/runtime bits. */
364	
365	  restore_sr0 = saved_sr0 & 0xfcu;
366	  return bk7258_clockdiag_flash_write_sr1(restore_sr0);
367	}
