415	static inline int bk7258_clockdiag_flash_write32_pattern(uint32_t addr)
416	{
417	  int diag;
418	  int ret;
419	  unsigned int i;
420	
421	  if (addr < BK7258_CDIAG_FS_D5_START ||
422	      addr >= BK7258_CDIAG_FS_D5_START + BK7258_CDIAG_FS_D5_WRITE_LEN ||
423	      (addr & 0x1fu) != 0)
424	    {
425	      return -1;
426	    }
427	
428	  diag = (addr == BK7258_CDIAG_FS_D5_START);
429	
430	  if (bk7258_clockdiag_flash_wait_ready() < 0)
431	    {
432	      return -1;
433	    }
434	
435	  if (diag)
436	    {
437	      bk7258_clockdiag_flash_d5_status("WB");
438	    }
439	
440	  if (bk7258_clockdiag_flash_wren_plain() < 0)
441	    {
442	      return -1;
443	    }
444	
445	  if (diag)
446	    {
447	      bk7258_clockdiag_flash_d5_status("WE");
448	    }
449	
450	  for (i = 0; i < 8; i++)
451	    {
452	      putreg32(BK7258_CDIAG_FS_D5_PATTERN,
453	                BK7258_CDIAG_FLASH_DATA_SW_FLASH);
454	    }
455	
456	  if (diag)
457	    {
458	      bk7258_clockdiag_flash_d5_regs("WS");
459	    }
460	
461	  ret = bk7258_clockdiag_flash_swop_plain(addr,
462	                                          BK7258_CDIAG_FLASH_OP_CMD_PP);
463	
464	  if (diag)
465	    {
466	      bk7258_clockdiag_flash_d5_status("WP");
467	    }
468	
469	  return ret;
470	}
