472	static inline int bk7258_clockdiag_flash_write_tail16_pattern(uint32_t addr)
473	{
474	  unsigned int i;
475	
476	  if (addr != BK7258_CDIAG_FS_D5_START +
477	              BK7258_CDIAG_FS_D5_WRITE_LEN - 0x10u)
478	    {
479	      return -1;
480	    }
481	
482	  if (bk7258_clockdiag_flash_wait_ready() < 0)
483	    {
484	      return -1;
485	    }
486	
487	  if (bk7258_clockdiag_flash_wren_plain() < 0)
488	    {
489	      return -1;
490	    }
491	
492	  /* D5-only tail coverage. Stage the same pattern in all slots; if the
493	    * controller writes more than 16B or wraps within the 256B page, it still
494	    * writes the same pattern and the sector is re-erased before exit.
495	    */
496	
497	  for (i = 0; i < 8; i++)
498	    {
499	      putreg32(BK7258_CDIAG_FS_D5_PATTERN,
500	                BK7258_CDIAG_FLASH_DATA_SW_FLASH);
501	    }
502	
503	  return bk7258_clockdiag_flash_swop_plain(addr,
504	                                            BK7258_CDIAG_FLASH_OP_CMD_PP);
505	}
506	static inline int bk7258_clockdiag_flash_verify_range(uint32_t start,
507	                                                      uint32_t end,
508	                                                      uint32_t expected)
509	{
510	  uint32_t addr;
511	  uint32_t buf[4];
512	  unsigned int i;
513	
514	  for (addr = start; addr < end; addr += 0x10u)
515	    {
516	      if (bk7258_clockdiag_flash_read16(addr, buf) < 0)
517	        {
518	          bk7258_clockdiag_puts("VERIFY TIMEOUT ");
519	          bk7258_clockdiag_putreg("OFF", addr);
520	          bk7258_clockdiag_puts("\r\n");
521	          return -1;
522	        }
523	
524	      for (i = 0; i < 4; i++)
525	        {
526	          if (buf[i] != expected)
527	            {
528	              bk7258_clockdiag_puts("VERIFY BAD ");
529	              bk7258_clockdiag_putreg("OFF", addr);
530	              bk7258_clockdiag_puts(" ");
531	              bk7258_clockdiag_putreg("EXP", expected);
532	              bk7258_clockdiag_puts(" ");
533	              bk7258_clockdiag_putreg("GOT", buf[i]);
534	              bk7258_clockdiag_puts("\r\n");
535	              return -1;
536	            }
537	        }
538	    }
539	
540	  return 0;
541	}
