545	static inline void bk7258_clockdiag_flash_d5_run(void)
546	{
547	  uint32_t addr;
548	  uint32_t saved_sr0 = 0;
549	  int sr_changed = 0;
550	  bk7258_clockdiag_puts("N5FS:D5\r\n");
551	
552	  bk7258_clockdiag_puts("PRE ");
553	  bk7258_clockdiag_flash_dump16(BK7258_CDIAG_FS_D5_START);
554	  bk7258_clockdiag_flash_d5_status("PB");
555	
556	  sr_changed = bk7258_clockdiag_flash_d5_unprotect(&saved_sr0);
557	  if (sr_changed < 0)
558	    {
559	      bk7258_clockdiag_puts("N5FS:D5 UNPROTFAIL\r\n");
560	      bk7258_clockdiag_flash_d5_restore(saved_sr0, sr_changed > 0);
561	      bk7258_clockdiag_flash_d5_status("PR");
562	      return;
563	    }
564	
565	  bk7258_clockdiag_flash_d5_status("PU");
566	  if (bk7258_clockdiag_flash_verify_range(
567	        BK7258_CDIAG_FS_D5_START,
568	        BK7258_CDIAG_FS_D5_START + BK7258_CDIAG_FS_D5_WRITE_LEN,
569	        0xffffffffu) < 0)
570	    {
571	      bk7258_clockdiag_puts("N5FS:D5 PREFAIL\r\n");
572	      bk7258_clockdiag_flash_d5_restore(saved_sr0, sr_changed > 0);
573	      bk7258_clockdiag_flash_d5_status("PR");
574	      return;
575	    }
576	
577	  if (bk7258_clockdiag_flash_erase_d5_sector() < 0)
578	    {
579	      bk7258_clockdiag_puts("N5FS:D5 ERASEFAIL\r\n");
580	      bk7258_clockdiag_flash_d5_restore(saved_sr0, sr_changed > 0);
581	      bk7258_clockdiag_flash_d5_status("PR");
582	      return;
583	    }
584	
585	  bk7258_clockdiag_puts("ERA OK\r\n");
586	  bk7258_clockdiag_puts("ERD ");
587	  bk7258_clockdiag_flash_dump16(BK7258_CDIAG_FS_D5_START);
588	
589	  if (bk7258_clockdiag_flash_verify_range(
590	        BK7258_CDIAG_FS_D5_START,
591	        BK7258_CDIAG_FS_D5_START + BK7258_CDIAG_FS_D5_WRITE_LEN,
592	        0xffffffffu) < 0)
593	    {
594	      bk7258_clockdiag_puts("N5FS:D5 ERDFAIL\r\n");
595	      bk7258_clockdiag_flash_d5_restore(saved_sr0, sr_changed > 0);
596	      bk7258_clockdiag_flash_d5_status("PR");
597	      return;
598	    }
599	
600	  for (addr = BK7258_CDIAG_FS_D5_START;
601	        addr <= BK7258_CDIAG_FS_D5_START +
602	                BK7258_CDIAG_FS_D5_WRITE_LEN - 0x20u;
603	        addr += 0x20u)
604	    {
605	      bk7258_clockdiag_puts("WO ");
606	      bk7258_clockdiag_putreg("OFF", addr);
607	      bk7258_clockdiag_puts("\r\n");
608	
609	      if (bk7258_clockdiag_flash_write32_pattern(addr) < 0)
610	        {
611	          bk7258_clockdiag_puts("N5FS:D5 WRITEFAIL ");
612	          bk7258_clockdiag_putreg("OFF", addr);
613	          bk7258_clockdiag_puts("\r\n");
614	
615	          bk7258_clockdiag_flash_erase_d5_sector();
616	          bk7258_clockdiag_flash_d5_restore(saved_sr0, sr_changed > 0);
617	          bk7258_clockdiag_flash_d5_status("PR");
618	          return;
619	        }

620	    }
621	  addr = BK7258_CDIAG_FS_D5_START +
622	           BK7258_CDIAG_FS_D5_WRITE_LEN - 0x10u;
623	
624	  bk7258_clockdiag_puts("WT ");
625	  bk7258_clockdiag_putreg("OFF", addr);
626	  bk7258_clockdiag_puts("\r\n");
627	
628	  if (bk7258_clockdiag_flash_write_tail16_pattern(addr) < 0)
629	    {
630	      bk7258_clockdiag_puts("N5FS:D5 TAILFAIL ");
631	      bk7258_clockdiag_putreg("OFF", addr);
632	      bk7258_clockdiag_puts("\r\n");
633	
634	      bk7258_clockdiag_flash_erase_d5_sector();
635	      bk7258_clockdiag_flash_d5_restore(saved_sr0, sr_changed > 0);
636	      bk7258_clockdiag_flash_d5_status("PR");
637	      return;
638	    }
639	  bk7258_clockdiag_puts("WR OK\r\n");
640	  bk7258_clockdiag_puts("WRD0 ");
641	  bk7258_clockdiag_flash_dump16(BK7258_CDIAG_FS_D5_START);
642	
643	  bk7258_clockdiag_puts("WRDE ");
644	  bk7258_clockdiag_flash_dump16(BK7258_CDIAG_FS_D5_START +
645	                                BK7258_CDIAG_FS_D5_WRITE_LEN - 0x20u);
646	
647	  bk7258_clockdiag_puts("WRDF ");
648	  bk7258_clockdiag_flash_dump16(BK7258_CDIAG_FS_D5_START +
649	                                BK7258_CDIAG_FS_D5_WRITE_LEN - 0x10u);
650	
651	  if (bk7258_clockdiag_flash_verify_range(
652	          BK7258_CDIAG_FS_D5_START,
653	          BK7258_CDIAG_FS_D5_START + BK7258_CDIAG_FS_D5_WRITE_LEN,
654	          BK7258_CDIAG_FS_D5_PATTERN) < 0)
655	    {
656	      bk7258_clockdiag_puts("N5FS:D5 WRDFAIL\r\n");
657	
658	      if (bk7258_clockdiag_flash_erase_d5_sector() == 0)
659	        {
660	          bk7258_clockdiag_puts("FAILCLR ");
661	          bk7258_clockdiag_flash_dump16(BK7258_CDIAG_FS_D5_START);
662	        }
663	      else
664	        {
665	          bk7258_clockdiag_puts("FAILCLR ERASEFAIL\r\n");
666	        }
667	
668	      bk7258_clockdiag_flash_d5_restore(saved_sr0, sr_changed > 0);
669	      bk7258_clockdiag_flash_d5_status("PR");
670	
671	      return;
672	    }
673	
674	  if (bk7258_clockdiag_flash_erase_d5_sector() < 0)
675	    {
676	      bk7258_clockdiag_puts("N5FS:D5 RERASEFAIL\r\n");
677	      bk7258_clockdiag_flash_d5_restore(saved_sr0, sr_changed > 0);
678	      bk7258_clockdiag_flash_d5_status("PR");
679	      return;
680	    }
681	
682	  bk7258_clockdiag_puts("RER OK\r\n");
683	  bk7258_clockdiag_puts("FIN ");
684	  bk7258_clockdiag_flash_dump16(BK7258_CDIAG_FS_D5_START);
685	
686	  if (bk7258_clockdiag_flash_verify_range(
687	        BK7258_CDIAG_FS_D5_START,
688	        BK7258_CDIAG_FS_D5_START + BK7258_CDIAG_FS_D5_WRITE_LEN,
689	        0xffffffffu) < 0)
690	    {
691	      bk7258_clockdiag_puts("N5FS:D5 FINFAIL\r\n");
692	      bk7258_clockdiag_flash_d5_restore(saved_sr0, sr_changed > 0);
693	      bk7258_clockdiag_flash_d5_status("PR");
694	      return;
695	    }
696	  if (bk7258_clockdiag_flash_d5_restore(saved_sr0, sr_changed > 0) < 0)
697	    {
698	      bk7258_clockdiag_puts("N5FS:D5 RESTFAIL\r\n");
699	      return;
700	    }
701	
702	  bk7258_clockdiag_flash_d5_status("PR");
703	  bk7258_clockdiag_puts("N5FS:D5 OK\r\n");
704	}
