712	static inline void bk7258_clockdiag_flash_find_magic(void)
713	{
714	  uint32_t addr;
715	  uint32_t buf[4];
716	
717	  bk7258_clockdiag_puts("N5FS:M\r\n");
718	
719	  for (addr = 0; addr < 0x00040000u; addr += 0x20u)
720	    {
721	      if (bk7258_clockdiag_flash_read16(addr, buf) < 0)
722	        {
723	          bk7258_clockdiag_putreg("TOFF", addr);
724	          bk7258_clockdiag_puts("\r\n");
725	          return;
726	        }
727	
728	      if (bk7258_clockdiag_has_bk_magic(buf[0], buf[1]))
729	        {
730	          bk7258_clockdiag_putreg("MAG", addr);
731	          bk7258_clockdiag_puts(" ");
732	          bk7258_clockdiag_putreg("W0", buf[0]);
733	          bk7258_clockdiag_puts(" ");
734	          bk7258_clockdiag_putreg("W1", buf[1]);
735	          bk7258_clockdiag_puts("\r\n");
736	          return;
737	        }
738	    }
739	
740	  bk7258_clockdiag_puts("MAG=NONE\r\n");
741	}
