148	static inline void bk7258_clockdiag_early_dump(void)
149	{
150	  uint32_t m1  = getreg32(BK7258_CDIAG_SYS_CPU_CLK_DIV_MODE1);
151	  uint32_t m2  = getreg32(BK7258_CDIAG_SYS_CPU_CLK_DIV_MODE2);
152	  uint32_t c0  = getreg32(BK7258_CDIAG_SYS_CPU0_HALT_CLK_OP);
153	  uint32_t a0  = getreg32(BK7258_CDIAG_SYS_ANA_REG0);
154	  uint32_t a1  = getreg32(BK7258_CDIAG_SYS_ANA_REG1);
155	  uint32_t a5  = getreg32(BK7258_CDIAG_SYS_ANA_REG5);
156	  uint32_t a8  = getreg32(BK7258_CDIAG_SYS_ANA_REG8);
157	  uint32_t a9  = getreg32(BK7258_CDIAG_SYS_ANA_REG9);
158	  uint32_t a10 = getreg32(BK7258_CDIAG_SYS_ANA_REG10);
159	  uint32_t a11 = getreg32(BK7258_CDIAG_SYS_ANA_REG11);
160	  uint32_t a12 = getreg32(BK7258_CDIAG_SYS_ANA_REG12);
161	  uint32_t a13 = getreg32(BK7258_CDIAG_SYS_ANA_REG13);
162	  uint32_t isr = getreg32(BK7258_CDIAG_SYS_CPU0_INT_32_63_STAT);
163	  uint32_t r7  = getreg32(BK7258_CDIAG_AON_PMU_R7D);
164	  uint32_t uc  = getreg32(BK7258_CDIAG_UART1_CFG_REG);
165	
166	  bk7258_clockdiag_puts("N4D0:E\r\n");
167	
168	  /* Raw-hex evidence line: every register the decode below references. */
169	
170	  bk7258_clockdiag_putreg("M1", m1);
171	  bk7258_clockdiag_putc(' ');
172	  bk7258_clockdiag_putreg("M2", m2);
173	  bk7258_clockdiag_putc(' ');
174	  bk7258_clockdiag_putreg("A0", a0);
175	  bk7258_clockdiag_putc(' ');
176	  bk7258_clockdiag_putreg("A1", a1);
177	  bk7258_clockdiag_putc(' ');
178	  bk7258_clockdiag_putreg("A5", a5);
179	  bk7258_clockdiag_putc(' ');
180	  bk7258_clockdiag_putreg("A9", a9);
181	  bk7258_clockdiag_putc(' ');
182	  bk7258_clockdiag_putreg("IS", isr);
183	  bk7258_clockdiag_putc(' ');
184	  bk7258_clockdiag_putreg("R7", r7);
185	  bk7258_clockdiag_putc(' ');
186	  bk7258_clockdiag_putreg("UC", uc);
187	  bk7258_clockdiag_putc(' ');
188	  bk7258_clockdiag_putreg("C0", c0);
189	  bk7258_clockdiag_puts("\r\n");
190	
191	  /* Extended analog batch raw line: ANA_REG8/10/11/12/13 -- the remaining
192	   * words the vendor early_init analog batch programs.  Emitted as raw hex
193	   * only (these are LDO/voltage/osc-cal registers, not clock-routing), so
194	   * the boot state can be diffed word-by-word against that batch.
195	   */
196	
197	  bk7258_clockdiag_putreg("A8", a8);
198	  bk7258_clockdiag_putc(' ');
199	  bk7258_clockdiag_putreg("AA", a10);
200	  bk7258_clockdiag_putc(' ');
201	  bk7258_clockdiag_putreg("AB", a11);
202	  bk7258_clockdiag_putc(' ');
203	  bk7258_clockdiag_putreg("AC", a12);
204	  bk7258_clockdiag_putc(' ');
205	  bk7258_clockdiag_putreg("AD", a13);
206	  bk7258_clockdiag_puts("\r\n");
207	
208	  /* Compact decode of the clock-critical fields. */
209	
210	  bk7258_clockdiag_putfield("csrc",  BK7258_CDIAG_F_CKSEL_CORE(m1),   1);
211	  bk7258_clockdiag_putfield(" cdiv", BK7258_CDIAG_F_CLKDIV_CORE(m1),  1);
212	  bk7258_clockdiag_putfield(" bdiv", BK7258_CDIAG_F_CLKDIV_BUS(m1),   1);
213	  bk7258_clockdiag_putfield(" usrc", BK7258_CDIAG_F_CKSEL_UART1(m1),  1);
214	  bk7258_clockdiag_putfield(" udiv", BK7258_CDIAG_F_CLKDIV_UART1(m1), 1);
215	  bk7258_clockdiag_putfield(" fsrc", BK7258_CDIAG_F_CKSEL_FLASH(m2),  1);
216	  bk7258_clockdiag_putfield(" fdiv", BK7258_CDIAG_F_CKDIV_FLASH(m2),  1);
