/* Start (if needed) and use SysTick free-running as a transient microsecond
 * delay.  Reload is reprogrammed for each delay so any leftover live reload
 * does not invalidate us.  Conservative: 100 ticks/us covers up to 100 MHz.
 */

static void bk7258_clk_sleep_us(uint32_t us)
{
  uint32_t reload = BK7258_CLK_DELAY_TICKS(us);

  BK7258_SYST_CSR  = 0;                         /* disable while reloading */
  BK7258_SYST_RVR  = reload;
  BK7258_SYST_CVR  = 0;                          /* clear to start from top */
  BK7258_SYST_CSR  = BK7258_SYST_CSR_ENABLE | BK7258_SYST_CSR_CLKSOURCE;

  while ((BK7258_SYST_CSR & BK7258_SYST_CSR_ENABLE) != 0 &&
         BK7258_SYST_CVR != 0 &&
         BK7258_SYST_CVR < reload)
    {
      /* COUNTFLAG (CSR[16]) could signal underflow; the simplest correct
       * check is "CSR still enabled and CVR is non-zero + below reload".
       */
    }

  BK7258_SYST_CSR = 0;                           /* stop the transient clock */
}

