  if (csrc == 0 && dplle == 0)
    {
      return BK7258_CDIAG_CASE_BASELINE;
    }

  if (csrc == 2 && cdiv == 3 && dplle)
    {
      return BK7258_CDIAG_CASE_LOADER80;
    }

  if (csrc == 3 && cdiv == 3 && dplle)
    {
      return BK7258_CDIAG_CASE_DPLL120;
