void bk7258_clock_bringup_320m(void)
{
  uint32_t a5;
  uint32_t dpll_on;

  /* Switch to 320 MHz when the DPLL is enabled.  The bootloader enables
   * and calibrates the DPLL but only writes the SDK default-branch analog
   * block -- it does NOT raise VDDIG/VDDD to the 320 MHz tier, leaving
   * VDDIG at the low default (0xB) where the DPLL cannot hold a 480 MHz
   * lock.  So before switching the core mux we raise the core voltages to
   * the 320 MHz tier (VDDIG 0xE / VDDD 0x7); without this the DPLL drops
   * to 240 MHz and cksel=2 yields 160 MHz (half-speed).  DPLL recalibration
   * is still left to the bootloader.
   */

  a5 = BK7258_REG(BK7258_ANA_REG5);
  dpll_on = ((a5 & BK7258_ANA5_EN_DPLL) != 0);

  if (dpll_on)
    {
      bk7258_raise_vdd();          /* VDDIG->0xE, VDDD->0x7 before mux switch */
      bk7258_recal_dpll_at_vdd();  /* acquire 480 MHz lock at the new voltage */
      bk7258_switch_to_320m();
    }

#ifdef CONFIG_BK7258_CLOCK_320M_PROBE
  {
    uint32_t m1 = BK7258_REG(BK7258_CPU_CLK_DIV_MODE1);
    uint32_t r5 = BK7258_REG(BK7258_ANA_REG5);
    uint32_t r9 = BK7258_REG(BK7258_ANA_REG9);

    bk7258_clk_puts("N4Clk M1=");
    bk7258_clk_puthex8(m1);
    bk7258_clk_puts(" A5=");
    bk7258_clk_puthex8(r5);
    bk7258_clk_puts(" A9=");
    bk7258_clk_puthex8(r9);
    bk7258_clk_puts(" DXPLL=");
    bk7258_clk_puthex8(dpll_on);
    bk7258_clk_puts("\r\n");
  }
#endif
}

